	ICONS = {
    		"info":         ("material/info",                   "#1E88E5", "Information"),  # blue
    		"alarm_active": ("material/notification_important", "#E53935", "Alarm Active"),  # red
    		"alarm_clear":  ("material/check_circle",           "#43A047", "Alarm Cleared"),  # green
    		"control":      ("material/warning",                "#FBC02D", "Control Action"),  # amber
		}

	DEFAULT_ICON = ("material/help_outline", "#FF8C00", "")

	columns = system.dataset.getColumnHeaders(value)
	data = []

	for row in range(value.getRowCount()):

		row_obj = {}
		for col in columns:
			cell = {"value": value.getValueAt(row, col)}
			row_obj[col] = cell

		cat = value.getValueAt(row, "event_category")
		path, color, tip = ICONS.get(cat, DEFAULT_ICON)
		icon_cell = {"path": path, "color": color, "tooltip": tip}

		row_obj["icon"] = icon_cell

		data.append(row_obj)

	return data
